'use strict';
const KEY='moh-ai-live-v1', SCHEMA=1;
const $=id=>document.getElementById(id), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID(), stamp=()=>new Date().toISOString(), words=t=>String(t).trim().split(/\s+/).filter(Boolean).length;
let storageFailed=false;
let discoveryReport=null;
const editorialSuggestions=new Map();
let state,pilot,currentDraft=null,currentView='home',editorTab='post',toastTimer,unsaved=false;
const safeURL=url=>{if(!url)return '';try{const u=new URL(url);if(u.protocol!=='https:'||u.username||u.password)return '';return u.href;}catch{return '';}};
function notify(text,error=false){clearTimeout(toastTimer);$('toast').textContent=text;$('toast').className=error?'error':'';$('toast').hidden=false;toastTimer=setTimeout(()=>$('toast').hidden=true,6500);}
function commit(text='השינויים נשמרו במכשיר הזה'){state.updatedAt=stamp();try{localStorage.setItem(KEY,JSON.stringify(state));storageFailed=false;$('save-status').innerHTML='<span class="live-dot"></span> נשמר במכשיר הזה';if(text)notify(text);return true;}catch{storageFailed=true;$('save-status').textContent='לא נשמר — הורידו גיבוי';notify('אין אפשרות לשמור בדפדפן. העבודה זמינה כרגע; הורידו גיבוי כדי לשמור אותה.',true);return false;}}
function download(name,data,type='text/plain;charset=utf-8'){const blob=data instanceof Blob?data:new Blob([data],{type});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function draft(){return state.drafts.find(d=>d.id===currentDraft);}
function source(id){return state.sources.find(s=>s.id===id);}
function status(d){return d.approvedVersion===d.version?['טקסט מאושר','green']:d.review?.version===d.version?['נבדקה · ממתינה לאישור','yellow']:['טיוטה לעריכה','gray'];}
function badge(label,kind=''){return `<span class="badge ${kind}">${esc(label)}</span>`;}
function safe(fn){return async(...args)=>{try{await fn(...args);}catch(e){notify(e.message||'הפעולה לא הושלמה',true);}};}
function go(view,id){if(unsaved&&!(view==='editor'&&id===currentDraft)){if(!confirm('יש שינויים שלא נשמרו. לעבור בלי לשמור אותם?'))return;unsaved=false;}currentView=view;if(id)currentDraft=id;editorTab='post';location.hash=view==='editor'?'editor/'+currentDraft:view;render();}
function render(){const names={home:'שולחן העבודה',sources:'המקורות שלי',drafts:'הטיוטות שלי',editor:'עריכת פוסט',journey:'הדרך לתוצר',settings:'הגדרות ומצב המערכת',discovery:'גילוי מקורות',demo:'דוגמה מלאה'};$('page-name').textContent=names[currentView]||names.home;document.querySelectorAll('[data-view]').forEach(b=>{const active=b.dataset.view===currentView||(currentView==='discovery'&&b.dataset.view==='sources');b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});$('source-count').textContent=state.sources.length;$('draft-count').textContent=state.drafts.length;const views={home:renderHome,sources:renderSources,drafts:renderDrafts,editor:renderEditor,journey:renderJourney,settings:renderSettings,discovery:renderDiscovery,demo:renderDemo};$('main').innerHTML=(views[currentView]||renderHome)();if(currentView==='editor'){bindEditor();drawCard();if(storageFailed)$('editor-status').textContent='השינויים בזיכרון בלבד — הורידו גיבוי';}if(currentView==='settings')$('voice-examples').addEventListener('input',()=>{unsaved=true;});$('main').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
function heading(title,subtitle,actions=''){return `<div class="page-heading"><div><p class="eyebrow">סטודיו התוכן של מוח AI</p><h1>${title}</h1><p class="muted">${subtitle}</p></div>${actions}</div>`;}
function renderHome(){const d=state.drafts.find(x=>x.id==='pilot-draft')||state.drafts[0];if(!d)return heading('מה הופכים היום לפוסט?','הוסיפו מקור ופתחו טיוטה כדי להתחיל.')+demoTeaser()+'<div class="empty-state"><h3>שולחן העבודה שלכם מוכן</h3><p>אפשר להתחיל ממקור חדש או מתוכן שכבר אספתם.</p><button class="button" data-action="add-source">הוספת מקור</button><button class="button ghost" data-action="new-draft">טיוטה חדשה</button></div>';const pending=state.drafts.filter(x=>x.approvedVersion!==x.version).length;return heading('מה הופכים היום לפוסט?','שלום עמית, כאן הופכים מידע מעניין לתוכן שהקהילה יכולה להבין ולנסות.',`<span class="date-tag">${esc(new Intl.DateTimeFormat('he-IL',{day:'numeric',month:'long',year:'numeric',timeZone:'Asia/Jerusalem'}).format(new Date()))}</span>`)+`
<div class="metrics"><div class="metric"><div class="metric-icon">▤</div><div><strong>${state.sources.length}</strong><span>מקורות בתיק העבודה</span></div></div><div class="metric"><div class="metric-icon">✎</div><div><strong>${state.drafts.length}</strong><span>טיוטות שהתחלנו</span></div></div><div class="metric"><div class="metric-icon">◷</div><div><strong>${pending}</strong><span>ממתינות לאישור שלך</span></div></div></div>
${demoTeaser()}${renderDiscoveryTeaser()}<div class="dashboard-grid"><section><div class="section-title"><h2>כבר יש משהו שאפשר לעבוד איתו</h2><button class="link-button" data-action="drafts">כל הטיוטות ←</button></div><article class="feature-card"><div class="feature-body"><div class="badges">${badge('הפיילוט הראשון')}${badge('מקור רשמי','gray')}</div><h2>בקשה ברורה יותר.<br>תשובה שימושית יותר.</h2><p>פוסט על שלושה פרטים שכדאי להוסיף לבקשה ל־AI, עם דוגמה שאפשר לנסות. המקור, הביקורת ושתי הגרסאות כבר בפנים.</p><button class="button" data-action="edit" data-id="${esc(d?.id||'')}">פתיחת הפוסט לעריכה <span>←</span></button></div><div class="feature-art"><img src="./assets/pilot-image.png" alt="כרטיס ההסבר מהפיילוט: למי כותבים, מה צריך לעשות ואיך להציג את התוצאה"></div></article></section>
<aside class="dashboard-aside"><div class="side-card"><div class="mini-label">תהליך קטן, תוצר ברור</div><h3>מהמקור ועד לפוסט</h3><ol class="step-list"><li><span class="step-num">1</span><div><strong>מוצאים מה שווה להסביר</strong>כתבה, תמלול או רעיון עם מקור</div></li><li><span class="step-num">2</span><div><strong>כותבים בגובה העיניים</strong>רעיון אחד, דוגמה ופעולה קטנה</div></li><li><span class="step-num">3</span><div><strong>בודקים ומוציאים תוצר</strong>טקסט ברור ותמונה שעוזרת להבין</div></li></ol></div><div class="side-card tinted"><div class="mini-label">הקול שלך, בהדרגה</div><h3>כאן לומדים לכתוב כמוך</h3><p>אפשר להוסיף דוגמאות כתיבה שלך. עד שתאשר את הסגנון, הקול יישאר מסומן כזמני.</p><button class="link-button" data-action="settings">הוספת דוגמאות כתיבה ←</button></div></aside></div>
<section class="angles-section"><div class="section-title"><h2>אותו מקור, שלוש זוויות לקהילה</h2><span class="muted">תרגול עריכה · לא סריקה יומית</span></div><div class="angle-grid">${[
['01','בקשה לפני ואחרי','להראות איך שלושה פרטים משנים את הבקשה, עם דוגמה קצרה.','השוואה'],['02','מה זה בכלל פרומפט?','להסביר מושג אחד בלי שפה מקצועית, ואז להזמין להתנסות.','מושג'],['03','תרגיל קטן לקהילה','לבקש מחברי הקהילה לשפר בקשה ישנה ולשתף מה השתנה.','תרגיל']].map(([n,t,p,angle])=>`<article class="angle-card"><span class="angle-number">זווית ${n}</span><h3>${t}</h3><p>${p}</p><button class="link-button" data-action="angle" data-angle="${angle}">פתיחת טיוטה מהזווית הזו ←</button></article>`).join('')}</div></section>`;}

function discoveryTime(){if(!discoveryReport)return '';return new Intl.DateTimeFormat('he-IL',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Jerusalem'}).format(new Date(discoveryReport.generated_at));}
function renderDiscoveryTeaser(){if(!discoveryReport)return `<section class="discovery-teaser"><div><p class="eyebrow">השלב הבא: מקורות אמיתיים</p><h2>מכותרת מעניינת לתיק תוכן</h2><p>כאן יופיע דוח גילוי ממקורות נבחרים, עם תאריכים ומצב נגישות.</p></div><button class="button ghost" data-action="discovery">פתיחת גילוי מקורות ←</button></section>`;const count=discoveryReport.items.length;return `<section class="discovery-teaser"><div><p class="eyebrow">איסוף אמיתי · ${esc(discoveryTime())}</p><h2>${count?`${count} כיוונים מהמקורות שנבדקו`:'הסריקה הסתיימה בלי פריטים מתאימים'}</h2><p>נתוני פיד בלבד. קריאת הכתבה ואימות הטענות מגיעים בשלב הבא.</p></div><button class="button" data-action="discovery">למקורות ולכיוונים ←</button></section>`;}
function renderDiscovery(){const headingBlock=heading('מה מצאנו במקורות?','דוח איסוף ממקורות ציבוריים. פתחו את הכתבה, הדביקו את הטקסט המלא, וקבלו שלוש זוויות עבודה עם קטעי ראיה מדויקים.',`<button class="button ghost small" data-action="sources">למקורות שלי</button>`);if(!discoveryReport)return headingBlock+'<div class="empty-state"><h3>עדיין אין דוח גילוי טעון</h3><p>אפשר להמשיך בהוספת מקור ידנית. אין כאן סריקה שמתחזה לתוצאה.</p><button class="button" data-action="add-source">הוספת מקור</button></div>';const report=discoveryReport;return headingBlock+`<div class="notice-inline">נאסף ב־${esc(discoveryTime())}, לפי שעון ישראל. זהו דוח שמור מהרצה, לא סריקה שמתבצעת עכשיו ולא עדכון אוטומטי בכל בוקר. ${report.collection_method==='connector_snapshot'?'הנתונים נאספו דרך חיבור חיצוני ולא בהרצת RSS ישירה.':''}</div><div class="feed-statuses">${report.sources.map(x=>`<div class="feed-status"><strong>${esc(x.title)}</strong>${badge(x.status==='failed'?'הגישה נכשלה':'המקור נבדק',x.status==='failed'?'yellow':'green')}${x.error?`<small>${esc(x.error)}</small>`:''}</div>`).join('')}</div><div class="discovery-list">${report.items.length?report.items.map((item,i)=>`<article class="source-card discovery-item"><span class="source-icon">${i+1}</span><div class="source-info"><div class="badges">${badge(item.source_name)}${badge(item.source_type==='video'?'דרוש תמלול':'דרושה קריאת כתבה','yellow')}${badge('טענות טרם אומתו','gray')}</div><h3 dir="auto">${esc(item.title)}</h3><p>${item.published_at?'פורסם: '+esc(new Date(item.published_at).toLocaleString('he-IL',{timeZone:'Asia/Jerusalem'})):'תאריך הפרסום לא ידוע'} · ציון התאמה לפי כללים: ${esc(item.score)}</p>${item.summary?`<p dir="auto">${esc(item.summary.slice(0,400))}</p>`:''}<div class="discovery-angle"><strong>כיוון אפשרי לפוסט</strong><p>${esc(item.suggested_angle)}</p><small>זו הצעת עריכה ראשונית, לא מסקנה מתוך הכתבה.</small></div><p class="data-note">למה נבחר: ${item.score_reason.map(esc).join(' · ')}</p><div class="source-actions"><a class="button ghost small" href="${esc(item.url)}" target="_blank" rel="noopener noreferrer">פתיחת הכתבה ↗</a></div><details class="paste-source"><summary>הדבקת הכתבה המלאה והכנת הצעות</summary><p>פתחו את המקור והדביקו כאן את גוף הכתבה (לפחות 500 תווים). הדפדפן לא קורא אוטומטית אתרים אחרים. אם מדובר בסרטון, הדביקו תמלול.</p><label for="article-text-${esc(item.id)}">טקסט מלא או תמלול</label><textarea id="article-text-${esc(item.id)}" rows="8" maxlength="150000" placeholder="הדביקו כאן את הכתבה או התמלול…"></textarea><button class="button small" data-action="analyze-item" data-id="${esc(item.id)}">הצעת שלוש זוויות</button><div id="angles-${esc(item.id)}" class="editorial-suggestions" aria-live="polite"></div></details></div></article>`).join(''):'<div class="empty-state"><h3>אין כרגע פריטים שעברו את סף הרלוונטיות והזמן</h3><p>לא מוסיפים ידיעות ישנות או לא מבוססות כדי למלא מכסה. אפשר לבדוק את מצב המקורות ולהוסיף מקור ידנית.</p></div>'}</div><p class="data-note">הדוח מבחין בין מועד פרסום לבין מועד איסוף. נתוני RSS/Atom אינם הוכחה שהכתבה נקראה או שהסרטון נצפה. התוצאה המוצגת אינה פוסט שנוצר במודל.</p>`;}

function renderSources(){return heading('מתחילים ממקור שאפשר לבדוק','קישור, טקסט ותמלול — עם הבחנה ברורה בין מה שקראנו לבין מה שעוד חסר.',`<div class="button-row"><button class="button ghost" data-action="discovery">גילוי מקורות</button><button class="button" data-action="add-source">＋ מקור חדש</button></div>`)+state.sources.map(s=>`<article class="source-card"><span class="source-icon">${s.basis==='transcript'?'▷':'▤'}</span><div class="source-info"><div class="badges">${badge(s.basis==='transcript'?'תמלול · ללא צפייה בווידאו':'מקור כתוב')}${badge(s.verified?'אומת ידנית מול מקור ראשוני':'ממתין לאימות',s.verified?'green':'yellow')}</div><h3>${esc(s.title)}</h3><p>נוסף ${esc(new Date(s.createdAt).toLocaleDateString('he-IL'))} · ${s.publishedAt?'פורסם '+esc(s.publishedAt):'תאריך הפרסום לא ידוע'}${s.coverage==='selected_excerpts'?' · נשמרו קטעי ראיה נבחרים בלבד':''}</p>${safeURL(s.url)?`<a class="source-link" target="_blank" rel="noopener noreferrer" href="${esc(s.url)}">${esc(s.url)}</a>`:''}<div class="source-actions"><button class="button ghost small" data-action="use-source" data-id="${esc(s.id)}">טיוטה מהמקור הזה</button><button class="link-button" data-action="edit-source" data-id="${esc(s.id)}">גרסה מעודכנת למקור</button><button class="link-button" data-action="toggle-source" aria-expanded="false" aria-controls="source-${esc(s.id)}" data-id="${esc(s.id)}">צפייה בטקסט ובראיה ↓</button></div><div id="source-${esc(s.id)}" class="source-details" hidden>${esc(s.content)}${s.claim?`\n\nטענה מתועדת: ${esc(s.claim)}\nראיה: ${esc(s.excerpt)}`:''}</div></div></article>`).join('')+(state.sources.length?'':`<div class="empty-state"><h3>איזה מקור נפתח ראשון?</h3><p>הוסיפו טקסט של כתבה או תמלול, ונשמור אותו לצד הטיוטה.</p><button class="button" data-action="add-source">הוספת מקור</button></div>`);}
function renderDrafts(){return heading('מה נמצא על שולחן העריכה?','הטיוטות ממוספרות לפי הסדר שמופיעות כאן. מחיקה מסירה את הטיוטה ואת היסטוריית הגרסאות שלה מהמכשיר הזה.',`<button class="button" data-action="new-draft">＋ טיוטה חדשה</button>`)+`<div class="draft-grid">${state.drafts.map((d,i)=>{const st=status(d),s=source(d.sourceId);return `<article class="draft-card"><div class="draft-card-head"><div class="badges">${badge('טיוטה '+String(i+1).padStart(2,'0'),'gray')}${badge(st[0],st[1])}${badge('קול זמני','gray')}</div><h3>${esc(d.title)}</h3><p>${esc(d.text.slice(0,170))}${d.text.length>170?'…':''}</p><p class="muted">מקור: ${esc(s?.title||'טרם נבחר מקור')}</p></div><div class="draft-card-footer"><span>גרסה ${d.version} · ${words(d.text)} מילים</span><div class="button-row"><button class="link-button" data-action="edit" data-id="${esc(d.id)}">המשך עריכה ←</button><button class="link-button" style="color:#a33131" data-action="delete-draft" data-id="${esc(d.id)}" aria-label="מחיקת טיוטה ${i+1}">מחיקה</button></div></div></article>`;}).join('')}</div>`+(state.drafts.length?'':`<div class="empty-state"><h3>אין עדיין טיוטות</h3><p>הוסיפו מקור או פתחו טיוטה חדשה כדי להתחיל.</p><button class="button" data-action="new-draft">יצירת טיוטה</button></div>`);}
function workflowMarkup(d,s,st){const verified=!!(s?.verified&&s.claim&&s.excerpt),hasText=!!d.text.trim(),reviewed=!!d.review&&d.review.version===d.version,approved=d.approvedVersion===d.version;const steps=[['1','מקור ותדריך',verified?'הטענה והראיה מתועדות':s?'המקור נבחר · כדאי לתעד טענה וראיה':'צריך לבחור מקור','workflow-source','פתיחת המקור'],['2','עריכת הפוסט',hasText?'הטיוטה מוכנה לעריכה':'הדביקו או כתבו טיוטה','editor-post','עריכת הנוסח'],['3','הכנת תמונה', 'כרטיס הסבר מקומי · אפשר לערוך ולהוריד PNG','workflow-visual','עריכת הכרטיס'],['4','ביקורת ואישור',approved?'הגרסה הנוכחית אושרה':reviewed?'הביקורת תועדה · ממתינה לאישור':'נדרשת ביקורת לפני אישור','editor-review',approved?'בדיקת האישור':'פתיחת הביקורת']];return `<section class="box workflow-box" aria-labelledby="workflow-title"><div class="section-title"><div><h2 id="workflow-title">מסלול העבודה · 1–2–3–4</h2><p class="muted">מתקדמים לפי הסדר; אפשר לחזור ולערוך בכל שלב.</p></div>${badge(approved?'מוכן להעתקה':reviewed?'מוכן לאישור':'בתהליך',approved?'green':'gray')}</div><div class="workflow-steps">${steps.map(([n,title,detail,target,label],i)=>`<article class="workflow-step"><span class="workflow-index">${n}</span><div class="workflow-copy"><h3>${title}</h3><p>${esc(detail)}</p><button class="link-button" data-workflow-target="${target}" data-workflow-tab="${target.startsWith('editor-')?target.slice(7):''}">${label} ←</button></div>${i<steps.length-1?'<span class="workflow-arrow" aria-hidden="true">←</span>':''}</article>`).join('')}</div><p class="small muted">הכתיבה והביקורת נשמרות במכשיר. כרגע אין חיבור למודל AI או פרסום אוטומטי; הכרטיס הגרפי נוצר בדפדפן.</p></section>`;}
function renderEditor(){const d=draft();if(!d)return heading('הטיוטה לא נמצאה','אפשר לחזור לספרייה ולבחור טיוטה קיימת.');const s=source(d.sourceId),st=status(d);return heading(esc(d.title),'עובדים על הפוסט שלב אחר שלב, עד לתוצר שאפשר להעתיק.')+workflowMarkup(d,s,st)+`<div class="editor-layout"><section><div class="box"><div class="badges badge-row">${badge(st[0],st[1])}${badge('קול זמני','gray')}${badge(d.origin==='assistant_session'?'הוכן בסשן העוזר':'עריכה ידנית','gray')}</div><input id="edit-title" class="editor-title" maxlength="160" aria-label="כותרת הפוסט" value="${esc(d.title)}"><label for="edit-source" class="muted">מקור לפוסט</label><select id="edit-source" class="source-select">${state.sources.map(x=>`<option value="${esc(x.id)}" ${x.id===d.sourceId?'selected':''}>${esc(x.title)}</option>`).join('')}</select><div class="tab-row"><button class="active" data-editor-tab="post">הפוסט</button><button data-editor-tab="review">ביקורת ושיפור</button><button data-editor-tab="history">גרסאות קודמות</button></div><div id="editor-post"><textarea id="edit-text" class="post-editor" maxlength="30000" aria-label="נוסח הפוסט" placeholder="הדביקו את הפוסט המקורי או כתבו טיוטה.">${esc(d.text)}</textarea><div class="editor-bottom"><span id="editor-status" class="editor-status">הגרסה הזו שמורה בדפדפן</span><span id="word-count" class="word-count">${words(d.text)} מילים</span></div></div><div id="editor-review" hidden>${reviewMarkup(d)}</div><div id="editor-history" hidden>${historyMarkup(d)}</div><div class="editor-toolbar"><button class="button" id="save-draft">שמירת גרסה</button><button class="button ghost" data-action="copy-post">העתקת טקסט</button><button class="button ghost" data-action="download-post">הורדת הפוסט</button><button class="link-button" data-action="structure">בדיקת מבנה</button></div><div id="structure-result" class="structure-result" hidden></div></div><div class="box" id="workflow-source"><div class="section-title"><h3>1 · המקור נשאר ליד הטקסט</h3>${s?.url?`<a class="link-button" href="${esc(safeURL(s.url))}" target="_blank" rel="noopener noreferrer">פתיחת המקור ↗</a>`:''}</div><p class="muted">${esc(s?.title||'בחרו מקור לפני אישור')}${s?.coverage==='selected_excerpts'?' · קטעי ראיה נבחרים; המסמך המלא נקרא בפיילוט':''}</p>${s?.claim?`<p class="data-note">${esc(s.claim)}</p><blockquote class="evidence-quote">${esc(s.excerpt)}</blockquote>`:'<p class="data-note">עדיין אין טענה וראיה מתועדות במקור הזה. אפשר לערוך טיוטה, אבל אישור דורש בדיקה ותיעוד.</p>'}<div class="button-row"><button class="button ghost small" data-action="manual-review">תיעוד ביקורת ידנית</button><button class="button light small" data-action="approve">אישור הטקסט</button></div></div></section><aside><div class="box" id="workflow-visual"><div class="section-title"><h3>3 · כרטיס הסבר לתמונה</h3>${badge('נוצר בדפדפן','gray')}</div><canvas id="card-canvas" class="card-canvas" width="1080" height="1350" aria-label="תצוגת כרטיס ההסבר"></canvas><p class="preview-caption">זהו כרטיס גרפי עם טקסט, לא תמונת AI או צילום. ערכו את המסרים ובדקו קריאות.</p><button class="button ghost" data-action="download-image">↓ הורדת תמונת PNG</button><details class="visual-controls"><summary>עריכת הכותרת ושלושת המסרים</summary><label>כותרת התמונה<input id="visual-title" maxlength="60" value="${esc(d.visual.title)}"></label>${d.visual.points.map((p,i)=>`<label>מסר ${i+1}<input data-visual-point="${i}" maxlength="90" value="${esc(p)}"></label>`).join('')}<p class="small muted">השינויים נשמרים יחד עם גרסת הפוסט. בדקו קריאות לפני שימוש.</p></details></div><div class="box"><h3>4 · רגע לפני שמוציאים</h3><p class="data-note">בדקו שהרעיון ברור, שהדוגמה מובנת, שהמקור תומך בטענות ושיש פעולה קטנה לקורא.</p><p class="data-note">אשרו רק אחרי שמירת הגרסה ותיעוד הביקורת. האישור אינו מפרסם; לאחריו העתיקו לוואטסאפ.</p></div></aside></div>`;}

function reviewMarkup(d){const r=d.review;if(!r)return '<div class="empty-state"><h3>עוד לא תועדה ביקורת</h3><p>אפשר לקרוא, לבדוק את המקור ולתעד מה כדאי לשפר.</p><button class="button ghost" data-action="manual-review">תיעוד ביקורת ידנית</button></div>';const current=r.version===d.version;return `<div class="badges">${badge(r.type==='ai_session'?'ביקורת AI מתועדת מהפיילוט':'ביקורת ידנית')}${badge(current?'על הגרסה הנוכחית':'על גרסה קודמת',current?'green':'yellow')}</div><p class="muted">${esc(r.reviewer)} · גרסה ${r.version}</p><ul class="review-findings">${r.findings.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="score-pills">${Object.entries(r.scores).map(([k,v])=>`<span class="score-pill">${({accuracy:'דיוק',clarity:'בהירות',usefulness:'שימושיות',voice:'שפה טבעית'})[k]||esc(k)} ${esc(v)}/5</span>`).join('')}</div><p class="review-note">דירוג השפה הוא זמני. טרם התקבלו דוגמאות כתיבה מאושרות של עמית. ביקורת AI אינה מקור עובדתי נוסף.</p>${d.id==='pilot-draft'?`<details><summary>מה השתנה בין v1 ל־v2?</summary><pre>${esc(pilot.review)}</pre></details>`:''}`;}
function historyMarkup(d){if(!d.history.length)return '<p class="muted">הגרסאות הקודמות יופיעו אחרי שמירת שינוי ראשון.</p>';return d.history.slice().reverse().map((h,i)=>`<div class="history-row"><div><b>גרסה ${h.version}</b><div class="muted">${esc(new Date(h.at).toLocaleDateString('he-IL'))} · ${words(h.text)} מילים</div></div><button class="link-button" data-action="view-history" aria-expanded="false" aria-controls="history-${d.history.length-1-i}" data-index="${d.history.length-1-i}">צפייה בטקסט ↓</button></div><div class="compare-block" id="history-${d.history.length-1-i}" hidden>${esc(h.text)}</div>`).join('');}
function renderJourney(){const sourceCount=state.sources.length,draftCount=state.drafts.length,approvedCount=state.drafts.filter(d=>status(d)[0]==='מאושר').length;return heading('מהפוסט לתוצר בשלושה שלבים','פותחים מקור, עורכים ובודקים, ואז מאשרים ומעתיקים לפרסום.')+`<div class="timeline">${[
['1','מוסיפים את הפוסט והמקור',sourceCount?`יש ${sourceCount} מקורות שמורים. פתחו מקור קיים או הוסיפו את הפוסט שעליו עובדים.`:'הדביקו את הטקסט המקורי, הוסיפו קישור אם יש, וציינו מה כדאי לבדוק.','sources','פתיחת המקורות'],
['2','עורכים ומקבלים ביקורת',draftCount?`יש ${draftCount} טיוטות. פתחו טיוטה, שפרו כותרת ונוסח, ותעדו הערות בלשונית הביקורת.`:'צרו טיוטה מתוך מקור, ערכו אותה, ובקשו מחבר צוות לבדוק דיוק ובהירות.','drafts','פתיחת הטיוטות'],
['3','מאשרים ומכינים לפרסום',approvedCount?`יש ${approvedCount} טיוטות מאושרות. העתיקו את הגרסה שאושרה והדביקו בערוץ הפרסום.`:'אשרו את גרסת הטקסט הסופית. האישור אינו מפרסם אוטומטית; לאחריו העתיקו את הטקסט לוואטסאפ או לערוץ הרצוי.','drafts','בחירת תוצר']
].map(([n,t,p,v,label])=>`<article class="timeline-item"><span class="timeline-index">${n}</span><div><h3>${t}</h3><p>${p}</p><button class="button small" data-view="${v}">${label} ←</button></div></article>`).join('')}</div><p class="muted" style="margin-top:18px">המקור, הטיוטה, הביקורת והאישור נשמרים יחד במכשיר הזה. אין פרסום או שליחה אוטומטיים.</p>`;}
function renderSettings(){return heading('הכל במקום אחד','מה עובד כאן, היכן נשמרת העבודה ומה עדיין צריך לחבר.')+`<div class="settings-grid"><section class="box settings-card"><h3>מה אפשר לעשות בקישור הזה?</h3>${[['עריכה ושמירת גרסאות','פעיל'],['הדבקת טקסט וייבוא תמלולים','פעיל'],['תיעוד ביקורת ואישור טקסט','פעיל'],['יצירת כרטיס PNG','פעיל'],['גיבוי ושחזור JSON','פעיל'],['ניתוח קישור אוטומטי','בהמשך'],['מודל AI לכתיבה אוטומטית','בהמשך'],['דוח גילוי מקורות אמיתי','פעיל'],['עדכון יומי אוטומטי לאתר','בהמשך'],['הפקת סרטון הדרכה','בהמשך']].map(([a,b])=>`<div class="capability"><span>${a}</span><span class="status-label ${b==='פעיל'?'':'pending'}">${b==='פעיל'?'●':'◷'} ${b}</span></div>`).join('')}<p style="margin-top:18px">לא מחובר שירות AI בתשלום. דוגמאות הפיילוט הוכנו בסשן העוזר והן אינן תוצאות של מודל שרץ באתר.</p></section><section><div class="box settings-card"><h3>ללמוד את הקול שלך</h3><p>שמור כאן דוגמאות שאתה אוהב. הן ייכללו בגיבוי, אבל עדיין לא מוזנות אוטומטית למודל ואין כאן למידת סגנון פעילה.</p><label>דוגמאות כתיבה שלך<textarea id="voice-examples" rows="8" maxlength="20000" placeholder="פוסט ראשון, פוסט שני, ולמה אהבת אותם…">${esc(state.voiceExamples||'')}</textarea></label><button class="button" data-action="save-voice">שמירת הדוגמאות</button></div><div class="box settings-card"><h3>העבודה נשמרת במכשיר הזה</h3><p>פתיחת האתר בטלפון אחר לא מעבירה אליו טיוטות אוטומטית. כדי להעביר עבודה או לשמור עותק, הורד גיבוי וטען אותו במכשיר השני.</p><div class="button-row"><button class="button ghost" data-action="backup">הורדת גיבוי</button><button class="button ghost" data-action="restore">טעינת גיבוי</button></div><p style="margin-top:15px">המקורות והטיוטות שלך אינם נשלחים לשרת על ידי הממשק. האירוח הפרטי תלוי בגישה לחשבון הנוכחי; גיבוי ניתן לפתוח גם בעותק הקוד.</p><a class="link-button" href="https://github.com/erezfamily-cmyk/moh-ai-community" target="_blank" rel="noopener noreferrer">למאגר הפרויקט ↗</a></div></section></div>`;}
function bindEditor(){for(const el of [$('edit-title'),$('edit-text'),$('edit-source'),$('visual-title'),...document.querySelectorAll('[data-visual-point]')])el.addEventListener('input',()=>{unsaved=true;$('editor-status').textContent='יש שינויים שלא נשמרו';$('word-count').textContent=words($('edit-text').value)+' מילים';if(el.id==='visual-title'||el.hasAttribute('data-visual-point'))drawCard();});$('save-draft').onclick=safe(()=>saveEditor());const tabs=[...document.querySelectorAll('[data-editor-tab]')];document.querySelector('.tab-row').setAttribute('role','tablist');document.querySelector('.tab-row').setAttribute('aria-label','תוכן הפוסט והבדיקות');tabs.forEach((b,i)=>{b.id='tab-'+b.dataset.editorTab;b.setAttribute('role','tab');b.setAttribute('aria-controls','editor-'+b.dataset.editorTab);b.setAttribute('aria-selected',String(i===0));b.tabIndex=i===0?0:-1;const panel=$('editor-'+b.dataset.editorTab);panel.setAttribute('role','tabpanel');panel.setAttribute('aria-labelledby',b.id);b.onclick=()=>{editorTab=b.dataset.editorTab;for(const t of ['post','review','history'])$('editor-'+t).hidden=t!==editorTab;tabs.forEach(x=>{const active=x===b;x.classList.toggle('active',active);x.setAttribute('aria-selected',String(active));x.tabIndex=active?0:-1;});};b.onkeydown=e=>{let n=i;if(e.key==='ArrowLeft')n=(i+1)%tabs.length;else if(e.key==='ArrowRight')n=(i+tabs.length-1)%tabs.length;else if(e.key==='Home')n=0;else if(e.key==='End')n=tabs.length-1;else return;e.preventDefault();tabs[n].click();tabs[n].focus();};});}
function saveEditor(){const d=draft();if(!d)return false;const title=$('edit-title').value.trim(),body=$('edit-text').value,visual={title:$('visual-title').value.trim(),points:[...document.querySelectorAll('[data-visual-point]')].map(e=>e.value.trim())};if(!title)throw Error('צריך כותרת לפוסט.');const sid=$('edit-source').value;if(!source(sid))throw Error('בחרו מקור לפוסט.');const changed=title!==d.title||body!==d.text||sid!==d.sourceId||JSON.stringify(visual)!==JSON.stringify(d.visual);if(!changed){unsaved=false;if(storageFailed){const ok=commit('השמירה בדפדפן הצליחה הפעם.');render();return ok;}notify('הגרסה כבר שמורה, אין שינויים חדשים.');return true;}if(d.history.length>=100)throw Error('הגעתם למגבלת הגרסאות לטיוטה. הורידו גיבוי ופתחו טיוטה חדשה.');d.history.push({version:d.version,title:d.title,text:d.text,at:d.updatedAt});d.version++;d.title=title;d.text=body;d.visual=visual;d.sourceId=sid;d.origin='manual';d.approvedVersion=null;d.updatedAt=stamp();unsaved=false;const persisted=commit('נשמרה גרסה חדשה. נדרשת ביקורת חדשה לפני אישור.');render();return persisted;}
function drawCard(){const c=$('card-canvas');if(!c)return true;const ctx=c.getContext('2d');if(!ctx)return false;const d=draft(),title=$('visual-title')?.value||d.visual.title,points=[...document.querySelectorAll('[data-visual-point]')].map(x=>x.value);const list=points.length?points:d.visual.points;let fits=true;ctx.fillStyle='#f5f5ef';ctx.fillRect(0,0,1080,1350);ctx.textAlign='right';ctx.direction='rtl';function label(t,x,y,size,color='#1e2c29',weight='normal'){ctx.font=`${weight} ${size}px Arial,sans-serif`;ctx.fillStyle=color;ctx.fillText(t,x,y);}function round(x,y,w,h,r,color){ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill();}function wrap(t,width,size){ctx.font=`${size}px Arial,sans-serif`;const lines=[];let line='';for(const word of t.split(/\s+/)){const candidate=line?line+' '+word:word;if(ctx.measureText(candidate).width>width&&line){lines.push(line);line=word;}else line=candidate;if(ctx.measureText(word).width>width)fits=false;}if(line)lines.push(line);return lines;}
label('מוח AI · לומדים דרך דוגמה',995,110,30,'#2c7455');let size=62,lines=wrap(title,900,size);while(lines.length>2&&size>38){size-=2;lines=wrap(title,900,size);}if(lines.length>2)fits=false;lines.slice(0,2).forEach((line,i)=>label(line,995,217+i*(size+15),size,'#1b3028','bold'));label('רעיון אחד, דוגמה אחת, משהו לנסות.',995,335,31,'#7a8871');for(let i=0;i<3;i++){const y=402+i*220;round(75,y,930,182,23,'#fff');round(902,y+33,62,62,31,'#194b3c');ctx.textAlign='center';label(String(i+1),945,y+76,34,'#fff');ctx.textAlign='right';const ls=wrap(list[i]||'הוסיפו כאן מסר קצר',775,36);if(ls.length>3)fits=false;ls.slice(0,3).forEach((line,j)=>label(line,860,y+63+j*49,36));}round(75,1115,930,110,18,'#e4ecda');label('קחו את הרעיון, נסו אותו ובדקו את התוצאה.',965,1180,30,'#355f38');label('המחשה · המקור וההסבר המלא בפוסט המצורף',995,1290,24,'#86957b');c.dataset.fits=fits?'true':'false';return fits;}
function newDraft(sid,title='טיוטה חדשה',text=''){if(state.drafts.length>=200)throw Error('מגבלת הטיוטות הושגה. הורידו גיבוי לפני פתיחת סביבת עבודה חדשה.');if(!source(sid)){openSource();notify('הוסיפו קודם מקור לפוסט.');return;}const d={id:uid(),sourceId:sid,title,text,version:1,origin:'manual',visual:{title:title==='טיוטה חדשה'?'רעיון אחד לקהילה':title.slice(0,60),points:['מה כדאי להבין?','איך זה יכול לעזור?','מה אפשר לנסות היום?']},history:[],review:null,approvedVersion:null,createdAt:stamp(),updatedAt:stamp()};state.drafts.unshift(d);commit('נפתחה טיוטה ידנית חדשה.');go('editor',d.id);}

function dialogFingerprint(dialog){const f=dialog.querySelector('form');if(!f)return '';return JSON.stringify([...f.elements].filter(e=>e.name&&e.type!=='file').map(e=>[e.name,e.type==='checkbox'?e.checked:e.value]));}
function dialogBaseline(dialog){dialog.dataset.initialForm=dialogFingerprint(dialog);}
function allowDialogClose(dialog){const current=dialogFingerprint(dialog);return !current||current===dialog.dataset.initialForm||confirm('יש בטופס שינויים שלא נשמרו. לסגור בלי לשמור אותם?');}

function openSource(base){const f=$('source-form');f.reset();delete f.dataset.base;delete f.dataset.publication;delete f.dataset.discoveryURL;if(base){f.dataset.base=base.id;f.dataset.publication=base.publishedAt||'';f.dataset.discoveryURL=base.url||'';for(const k of ['title','url','content','claim','excerpt'])f.elements[k].value=base[k]||'';f.elements.verified.checked=base.verified;f.elements.kind.value=base.basis==='transcript'?'transcript':'article';}dialogBaseline($('source-dialog'));if(!$('source-dialog').open)$('source-dialog').showModal();}
function exportPost(){const d=draft(),s=source(d.sourceId),body=$('edit-text')?.value??d.text;const approved=!unsaved&&d.approvedVersion===d.version;const text=(approved?'':'> טיוטה לבדיקה — טרם אושרה לפרסום.\n\n')+'# '+($('edit-title')?.value||d.title)+'\n\n'+body+(s?.url&&!body.includes(s.url)?'\n\nמקור: '+s.url:'')+'\n\n<!-- קול זמני; התמונה דורשת בדיקה נפרדת. -->\n';download('moh-ai-post.md',text,'text/markdown;charset=utf-8');}
function backup(){download('moh-ai-backup-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(state,null,2),'application/json');notify('הגיבוי מוכן להורדה. שמרו אותו במקום שתוכלו למצוא.');}
const actions={demo:()=>go('demo'),'demo-edit':editGuidedDemo,'demo-step':b=>{const e=$('demo-step-'+b.dataset.step);if(e){e.scrollIntoView({behavior:'instant',block:'start'});e.focus({preventScroll:true});}},'demo-copy':async()=>{if(!navigator.clipboard)throw Error('אפשר לסמן את הטקסט ולהעתיק, או להוריד אותו כקובץ.');await navigator.clipboard.writeText(guidedDemo.v2);notify('הפוסט הועתק. טרם אושר לפרסום.');},discovery:()=>go('discovery'),'analyze-item':b=>{const item=discoveryReport?.items.find(x=>x.id===b.dataset.id),content=$('article-text-'+b.dataset.id)?.value||'';if(!item)throw Error('הפריט לא נמצא בדוח.');const angles=MohCore.proposeEditorialAngles({title:item.title,content,analysis_basis:'full_text'});editorialSuggestions.set(item.id,{content,angles});const target=$('angles-'+item.id);target.innerHTML='<p class="data-note">שלוש הצעות תבניתיות לפי הטקסט שהודבק. אין כאן מודל AI, בדיקת עובדות או אימות מול המקור.</p>'+angles.map(a=>`<article class="discovery-angle"><strong>${esc(a.title)}</strong><p>${esc(a.angle)}</p><small>קטע מהטקסט שסופק:</small><blockquote class="evidence-quote">${esc(a.evidence[0])}</blockquote><button class="button ghost small" data-action="use-angle" data-id="${esc(item.id)}" data-angle="${esc(a.id)}">פתיחה בתיק תוכן</button></article>`).join('');},'use-angle':b=>{const item=discoveryReport?.items.find(x=>x.id===b.dataset.id),proposal=editorialSuggestions.get(b.dataset.id),angle=proposal?.angles.find(x=>x.id===b.dataset.angle);if(!item||!proposal||!angle)throw Error('ההצעה פגה. הדביקו את הטקסט והפיקו אותה שוב.');openSource();const f=$('source-form');f.elements.title.value=item.title.slice(0,160);f.elements.url.value=item.url;f.elements.content.value=proposal.content;f.elements.claim.value=angle.angle;f.elements.excerpt.value=angle.evidence[0];f.elements.verified.checked=false;f.elements.kind.value=item.source_type==='video'?'transcript':'article';f.dataset.publication=item.published_at||'';f.dataset.discoveryURL=item.url;dialogBaseline($('source-dialog'));notify('הטקסט והראיה הועברו לתיק. עברו עליהם, שמרו, ואל תסמנו אימות לפני השוואה למקור.');},home:()=>go('home'),sources:()=>go('sources'),drafts:()=>go('drafts'),settings:()=>go('settings'),'add-source':()=>openSource(),'new-draft':()=>newDraft(state.sources[0]?.id),'delete-draft':b=>{const d=state.drafts.find(x=>x.id===b.dataset.id);if(!d)return;if(!window.confirm('למחוק את הטיוטה ״'+d.title+'״ ואת היסטוריית הגרסאות שלה? אי אפשר לשחזר אותה.'))return;state.drafts=state.drafts.filter(x=>x.id!==d.id);if(currentDraft===d.id){currentDraft=null;go('drafts');}commit('הטיוטה נמחקה.');render();},edit:b=>go('editor',b.dataset.id),'use-source':b=>{const src=source(b.dataset.id);if(!src)throw Error('המקור לא נמצא.');newDraft(src.id,src.title,src.content.slice(0,30000));if(src.content.length>30000)notify('המקור ארוך מ־30,000 תווים; הועתקו 30,000 התווים הראשונים לטיוטה.');else notify('הפוסט נפתח בעורך עם הטקסט שהדבקת כמקור. ערכו אותו ושמרו גרסה.');},'toggle-source':b=>{const e=$('source-'+b.dataset.id);e.hidden=!e.hidden;b.setAttribute('aria-expanded',String(!e.hidden));},'edit-source':b=>openSource(source(b.dataset.id)),angle:b=>{const titles={'השוואה':'בקשה לפני ואחרי','מושג':'מה זה בכלל פרומפט?','תרגיל':'תרגיל קטן לקהילת מוח AI'};newDraft('pilot-source',titles[b.dataset.angle]||'זווית חדשה','');notify('נפתחה טיוטה ריקה מהזווית שבחרתם. אין כאן יצירה אוטומטית של פוסט.');},'copy-post':async()=>{const text=$('edit-text')?.value??draft().text;if(!navigator.clipboard)throw Error('העתקה אוטומטית אינה זמינה. אפשר לסמן את הטקסט או להוריד קובץ.');await navigator.clipboard.writeText(text);notify('הטקסט הועתק.');},'download-post':()=>exportPost(),'download-image':()=>{if(!drawCard())throw Error('אחד הטקסטים ארוך מדי לתמונה. קצרו את הכותרת או המסרים ונסו שוב.');$('card-canvas').toBlob(blob=>{if(blob){download('moh-ai-explainer.png',blob,'image/png');notify('התמונה מוכנה. בדקו קריאות לפני פרסום.');}else notify('לא ניתן לייצא את התמונה בדפדפן הזה.',true);},'image/png');},structure:()=>{const body=$('edit-text').value,n=words(body),s=source($('edit-source').value);$('structure-result').hidden=false;$('structure-result').textContent=`בדיקת מבנה בלבד — לא ביקורת AI או בדיקת עובדות.\n${n} מילים · ${n<40?'כדאי להוסיף הסבר ודוגמה.':n>250?'אולי אפשר לקצר כדי לשמור על רעיון אחד.':'האורך מתאים לפוסט קצר.'}\n${s?.url?'מקור מקושר קיים.':'חסר קישור למקור.'}\nקראו ובדקו בעצמכם: האם כל טענה נשענת על המקור? האם הדוגמה ברורה?`;'use strict';},'manual-review':()=>{if(unsaved)throw Error('שמרו קודם את השינויים, כדי שהביקורת תהיה משויכת לגרסה המדויקת.');$('review-form').reset();dialogBaseline($('review-dialog'));$('review-dialog').showModal();},approve:()=>{const d=draft(),error=MohCore.canApprove(d,source(d.sourceId),unsaved);if(error)throw Error(error);$('confirm-dialog').showModal();},'view-history':b=>{const e=$('history-'+b.dataset.index);e.hidden=!e.hidden;b.setAttribute('aria-expanded',String(!e.hidden));},'save-voice':()=>{state.voiceExamples=$('voice-examples').value;unsaved=false;commit('הדוגמאות נשמרו. הן עדיין לא משמשות למודל באופן אוטומטי.');},backup,restore:()=>$('backup-file').click()};
document.addEventListener('click',safe(async e=>{const flow=e.target.closest('[data-workflow-target]');if(flow){const tab=flow.dataset.workflowTab;if(tab)document.querySelector('[data-editor-tab="'+tab+'"]')?.click();document.getElementById(flow.dataset.workflowTarget)?.scrollIntoView({behavior:'smooth',block:'center'});return;}if(e.target.closest('a.logo')){e.preventDefault();go('home');return;}const view=e.target.closest('[data-view]');if(view){go(view.dataset.view);return;}const b=e.target.closest('[data-action]');if(b&&actions[b.dataset.action]){await actions[b.dataset.action](b);return;}if(e.target.closest('.close-dialog')){const dialog=e.target.closest('dialog');if(allowDialogClose(dialog))dialog.close();}}));
document.querySelectorAll('dialog').forEach(dialog=>dialog.addEventListener('cancel',e=>{if(!allowDialogClose(dialog))e.preventDefault();}));
$('top-new').onclick=safe(()=>newDraft(state.sources[0]?.id));$('backup').onclick=safe(backup);$('restore').onclick=()=>$('backup-file').click();
$('source-form').addEventListener('submit',safe(e=>{e.preventDefault();const f=e.currentTarget,title=f.elements.title.value.trim(),content=f.elements.content.value.trim(),rawURL=f.elements.url.value.trim(),url=safeURL(rawURL),claim=f.elements.claim.value.trim(),excerpt=f.elements.excerpt.value.trim(),verified=f.elements.verified.checked;if(!title||!content)throw Error('צריך כותרת ותוכן מקור.');if(rawURL&&!url)throw Error('השתמשו בקישור HTTPS תקין ללא פרטי כניסה.');if(content.length>150000)throw Error('הטקסט ארוך מדי. צמצמו או פצלו את המקור.');if(excerpt&&!content.includes(excerpt))throw Error('קטע הראיה צריך להופיע בדיוק בטקסט המקור.');if(verified&&(!claim||!excerpt))throw Error('אימות דורש טענה וקטע ראיה מדויק.');if(state.sources.length>=100)throw Error('מגבלת המקורות הושגה. הורידו גיבוי לפני הוספה.');state.sources.unshift({id:uid(),title,url,content,claim,excerpt,verified,basis:f.elements.kind.value==='article'?'full_text':'transcript',coverage:'supplied_content',createdAt:stamp(),publishedAt:(f.dataset.discoveryURL===url?f.dataset.publication:null)||null});const wasCopy=!!f.dataset.base;$('source-dialog').close();commit(wasCopy?'נשמרה גרסה חדשה של המקור; המקור הקודם נשמר.':'המקור נשמר. אפשר להתחיל טיוטה.');go('sources');}));
$('source-file').addEventListener('change',safe(async e=>{const file=e.target.files[0];if(!file)return;if(file.size>600000)throw Error('הקובץ גדול מדי. בחרו קובץ קטן מ־600KB.');const content=await file.text();if(content.length>150000)throw Error('התמלול ארוך מדי לגרסה הזו. פצלו אותו לחלקים.');$('source-form').elements.content.value=content;if(file.name.endsWith('.vtt'))$('source-form').elements.kind.value='vtt';if(file.name.endsWith('.srt'))$('source-form').elements.kind.value='srt';if(!$('source-form').elements.title.value)$('source-form').elements.title.value=file.name.slice(0,160);notify('הקובץ נטען לטופס. שמרו את המקור כדי להמשיך.');}));
$('review-form').addEventListener('submit',safe(e=>{e.preventDefault();if(unsaved)throw Error('יש שינויים שלא נשמרו. שמרו גרסה לפני הביקורת.');const d=draft(),f=e.currentTarget,scores={};for(const k of ['accuracy','clarity','usefulness','voice']){scores[k]=Number(f.elements[k].value);if(!Number.isInteger(scores[k])||scores[k]<1||scores[k]>5)throw Error('בחרו ציון בין 1 ל־5 בכל מדד.');}if(!f.elements.checked.checked)throw Error('אשרו שקראתם והשוויתם למקור.');d.review={version:d.version,reviewer:f.elements.reviewer.value.trim(),type:'human',scores,blocking:f.elements.blocking.checked,findings:f.elements.findings.value.split('\n').map(x=>x.trim()).filter(Boolean)};d.approvedVersion=null;$('review-dialog').close();commit('הביקורת נשמרה לגרסה הנוכחית.');render();document.querySelector('[data-editor-tab="review"]').click();}));
$('confirm-approve').onclick=safe(()=>{const d=draft(),error=MohCore.canApprove(d,source(d.sourceId),unsaved);if(error)throw Error(error);d.approvedVersion=d.version;$('confirm-dialog').close();commit('הטקסט אושר לגרסה הזו. שום דבר לא פורסם.');render();});
$('backup-file').addEventListener('change',safe(async e=>{const file=e.target.files[0];if(!file)return;if(file.size>8*1024*1024)throw Error('הגיבוי גדול מדי לגרסה הזו.');let input;try{input=JSON.parse(await file.text());}catch{throw Error('הקובץ אינו JSON תקין.');}const next=MohCore.validateBackup(input);if(!confirm('טעינת גיבוי תחליף את העבודה בדפדפן הזה. הורידו קודם גיבוי של העבודה הנוכחית. להמשיך?'))return;for(const d of next.drafts)d.approvedVersion=null;state=next;unsaved=false;commit('הגיבוי נטען. אישורי טקסט דורשים אישור מחדש במכשיר הזה.');currentDraft=state.drafts[0]?.id;go('drafts');e.target.value='';}));
window.addEventListener('beforeunload',e=>{if(unsaved||storageFailed){e.preventDefault();e.returnValue='';}});
window.addEventListener('hashchange',()=>{const route=location.hash.slice(1);const v=route.startsWith('editor/')?'editor':route;const id=v==='editor'?route.slice(7):currentDraft;if(!['home','sources','drafts','editor','journey','settings','discovery','demo'].includes(v))return;if(v===currentView&&(v!=='editor'||id===currentDraft))return;if(unsaved){location.hash=currentView==='editor'?'editor/'+currentDraft:currentView;notify('יש שינויים שלא נשמרו. שמרו אותם לפני מעבר.');return;}currentView=v;currentDraft=id;render();});
async function init(){await loadGuidedDemo();try{const response=await fetch('./assets/discovery.json',{cache:'no-store'});if(response.ok)discoveryReport=MohCore.validateDiscoveryReport(await response.json());}catch{}const res=await fetch('./assets/pilot.json');if(!res.ok)throw Error('לא ניתן לטעון את הפיילוט. נסו לרענן.');pilot=await res.json();const s=pilot.evidence.source;const findings=(pilot.reviewReport.findings||[]).map(x=>typeof x==='string'?x:Object.values(x).join(' · '));const initial={schemaVersion:SCHEMA,sources:[{id:'pilot-source',title:'המדריך של OpenAI לבקשות ברורות',url:s.url,content:s.content,claim:pilot.evidence.claims.map(c=>c.statement).join(' '),excerpt:s.content,verified:true,basis:'full_text',coverage:'selected_excerpts',createdAt:s.retrieved_at,publishedAt:null}],drafts:[{id:'pilot-draft',sourceId:'pilot-source',title:'בקשה ברורה ל־AI',text:pilot.v2,version:2,origin:'assistant_session',visual:{title:'בקשה ברורה ל־AI',points:['למי כותבים? ציינו מי יקרא את התשובה.','מה צריך לעשות? בחרו משימה אחת ברורה.','איך להציג את התוצאה? בקשו אורך, שפה או מבנה.']},history:[{version:1,title:'בקשה ברורה ל־AI',text:pilot.v1,at:s.retrieved_at}],review:{version:2,type:'ai_session',reviewer:'מבקר התוכן בסשן הפיילוט',findings,scores:pilot.reviewReport.scores,blocking:pilot.reviewReport.blocking},approvedVersion:null,createdAt:s.retrieved_at,updatedAt:s.retrieved_at}],voiceExamples:'',updatedAt:stamp()};state=initial;try{const raw=localStorage.getItem(KEY);if(raw)state=MohCore.validateBackup(JSON.parse(raw));}catch{notify('הנתונים השמורים לא נטענו. הגיבוי הקודם לא נדרס; מוצג כעת הפיילוט הראשוני.',true);}currentDraft=state.drafts[0]?.id;const route=location.hash.slice(1);if(route.startsWith('editor/')&&state.drafts.some(d=>d.id===route.slice(7))){currentView='editor';currentDraft=route.slice(7);}else if(['home','sources','drafts','journey','settings','discovery','demo'].includes(route))currentView=route;render();}
init().catch(e=>{$('main').innerHTML='<div class="empty-state"><h1>לא הצלחנו לטעון את סביבת העבודה</h1><p>נסו לרענן את העמוד. העבודה השמורה בדפדפן לא נמחקה.</p></div>';notify(e.message,true);});
